const S=(pattern,cn,example)=>({pattern,cn,example}),E=(text,cn,example)=>({text,cn,example}),M=(wrong,correct,why)=>({wrong,correct,why});
const W=(viewpoint,topicSentence,collocations,argument)=>({viewpoint,topicSentence,collocations,argument});
const Q=(type,prompt,answer,explanation,options)=>Object.assign({type,prompt,answer,explanation},options?{options}:{});
const set=(id,x)=>Object.assign(days[id],x);

